package logfan

import (
	"context"
	"log/slog"
	"sync"
)

// Ring is an in-memory ring-buffer slog handler that keeps the most recent
// capacity records. It implements slog.Handler and is safe for concurrent use.
type Ring struct {
	mu       sync.Mutex
	capacity int
	buf      []slog.Record
	pos      int   // next write index
	count    int   // number of records stored (capped at capacity)
	level    slog.Leveler
	preAttrs []slog.Attr
	prefixes []string
}

// NewRing creates a Ring with the given capacity.
// Returns an error if capacity <= 0.
func NewRing(capacity int) (*Ring, error) {
	if capacity <= 0 {
		return nil, errInvalidCapacity
	}
	return &Ring{
		capacity: capacity,
		buf:      make([]slog.Record, capacity),
		level:    slog.LevelDebug,
	}, nil
}

var errInvalidCapacity = &capacityError{}

type capacityError struct{}

func (e *capacityError) Error() string { return "logfan: capacity must be positive" }

// Enabled reports whether the handler handles records at the given level.
func (r *Ring) Enabled(_ context.Context, level slog.Level) bool {
	return level >= r.level.Level()
}

// Handle stores a copy of the record in the ring buffer, evicting the oldest
// record when the buffer is full. Pre-defined attrs and groups (set via
// WithAttrs/WithGroup) are added to the record before storage.
func (r *Ring) Handle(_ context.Context, record slog.Record) error {
	rec := record.Clone()

	// Apply pre-defined attrs, nested in groups if any.
	if len(r.prefixes) > 0 {
		attrs := make([]slog.Attr, len(r.preAttrs))
		copy(attrs, r.preAttrs)
		for i := len(r.prefixes) - 1; i >= 0; i-- {
			attrs = []slog.Attr{slog.Group(r.prefixes[i], attrs...)}
		}
		rec.AddAttrs(attrs...)
	} else {
		rec.AddAttrs(r.preAttrs...)
	}

	r.mu.Lock()
	r.buf[r.pos] = rec
	r.pos = (r.pos + 1) % r.capacity
	if r.count < r.capacity {
		r.count++
	}
	r.mu.Unlock()
	return nil
}

// WithAttrs returns a new Ring that adds the given attrs to each record.
// The underlying ring buffer is shared.
func (r *Ring) WithAttrs(attrs []slog.Attr) slog.Handler {
	r2 := r.clone()
	r2.preAttrs = append(r2.preAttrs, attrs...)
	return r2
}

// WithGroup returns a new Ring that groups subsequent attrs under the given name.
func (r *Ring) WithGroup(name string) slog.Handler {
	r2 := r.clone()
	r2.prefixes = append(r2.prefixes, name)
	return r2
}

// Records returns the buffered records, oldest first, as a copy.
func (r *Ring) Records() []slog.Record {
	r.mu.Lock()
	defer r.mu.Unlock()

	result := make([]slog.Record, r.count)
	if r.count == 0 {
		return result
	}

	if r.count < r.capacity {
		for i := 0; i < r.count; i++ {
			result[i] = r.buf[i].Clone()
		}
	} else {
		// Buffer is full; records wrap around starting at r.pos.
		for i := 0; i < r.capacity; i++ {
			idx := (r.pos + i) % r.capacity
			result[i] = r.buf[idx].Clone()
		}
	}
	return result
}

// clone returns a shallow copy of r suitable for WithAttrs/WithGroup.
// The underlying buffer slice and mutex are shared.
func (r *Ring) clone() *Ring {
	return &Ring{
		capacity: r.capacity,
		buf:      r.buf,
		pos:      r.pos,
		count:    r.count,
		level:    r.level,
		preAttrs: r.preAttrs,
		prefixes: r.prefixes,
	}
}

package logfan

import (
	"context"
	"log/slog"
	"sync"
)

// ringState holds the mutable ring buffer state, shared across all clones
// created by WithAttrs/WithGroup. Its own mutex protects concurrent access.
type ringState struct {
	mu       sync.Mutex
	capacity int
	buf      []slog.Record
	pos      int // next write index
	count    int // number of records stored (capped at capacity)
}

// Ring is an in-memory ring-buffer slog handler that keeps the most recent
// capacity records. It implements slog.Handler and is safe for concurrent use.
type Ring struct {
	state    *ringState
	level    slog.Leveler
	preAttrs []slog.Attr
	prefixes []string
}

// NewRing creates a Ring with the given capacity.
// Returns an error if capacity <= 0.
func NewRing(capacity int) (*Ring, error) {
	if capacity <= 0 {
		return nil, errInvalidCapacity
	}
	return &Ring{
		state: &ringState{
			capacity: capacity,
			buf:      make([]slog.Record, capacity),
		},
		level: slog.LevelDebug,
	}, nil
}

var errInvalidCapacity = &capacityError{}

type capacityError struct{}

func (e *capacityError) Error() string { return "logfan: capacity must be positive" }

// Enabled reports whether the handler handles records at the given level.
func (r *Ring) Enabled(_ context.Context, level slog.Level) bool {
	return level >= r.level.Level()
}

// Handle stores a copy of the record in the ring buffer, evicting the oldest
// record when the buffer is full. Pre-defined attrs and groups (set via
// WithAttrs/WithGroup) are added to the record before storage.
func (r *Ring) Handle(_ context.Context, record slog.Record) error {
	rec := record.Clone()

	// Apply pre-defined attrs, nested in groups if any.
	if len(r.prefixes) > 0 {
		attrs := make([]slog.Attr, len(r.preAttrs))
		copy(attrs, r.preAttrs)
		for i := len(r.prefixes) - 1; i >= 0; i-- {
			attrs = []slog.Attr{slog.Group(r.prefixes[i], attrs...)}
		}
		rec.AddAttrs(attrs...)
	} else {
		rec.AddAttrs(r.preAttrs...)
	}

	s := r.state
	s.mu.Lock()
	s.buf[s.pos] = rec
	s.pos = (s.pos + 1) % s.capacity
	if s.count < s.capacity {
		s.count++
	}
	s.mu.Unlock()
	return nil
}

// WithAttrs returns a new Ring that adds the given attrs to each record.
// The underlying ring buffer is shared.
func (r *Ring) WithAttrs(attrs []slog.Attr) slog.Handler {
	r2 := &Ring{
		state: r.state,
		level: r.level,
	}
	r2.preAttrs = append(r2.preAttrs, r.preAttrs...)
	r2.preAttrs = append(r2.preAttrs, attrs...)
	r2.prefixes = append(r2.prefixes, r.prefixes...)
	return r2
}

// WithGroup returns a new Ring that groups subsequent attrs under the given name.
func (r *Ring) WithGroup(name string) slog.Handler {
	r2 := &Ring{
		state:    r.state,
		level:    r.level,
		preAttrs: r.preAttrs,
	}
	r2.prefixes = append(r2.prefixes, r.prefixes...)
	r2.prefixes = append(r2.prefixes, name)
	return r2
}

// Records returns the buffered records, oldest first, as a copy.
// Mutating the returned slice does not affect the ring.
func (r *Ring) Records() []slog.Record {
	s := r.state
	s.mu.Lock()
	defer s.mu.Unlock()

	result := make([]slog.Record, s.count)
	if s.count == 0 {
		return result
	}

	if s.count < s.capacity {
		for i := 0; i < s.count; i++ {
			result[i] = s.buf[i].Clone()
		}
	} else {
		// Buffer is full; records wrap around starting at r.state.pos.
		for i := 0; i < s.capacity; i++ {
			idx := (s.pos + i) % s.capacity
			result[i] = s.buf[idx].Clone()
		}
	}
	return result
}

package logfan

import (
	"log/slog"
)

var errNoHandlers = &noHandlersError{}

type noHandlersError struct{}

func (e *noHandlersError) Error() string { return "logfan: at least one handler required" }

// New builds a logger that delivers every record to ALL given handlers.
// Returns an error when called with no handlers.
func New(handlers ...slog.Handler) (*slog.Logger, error) {
	if len(handlers) == 0 {
		return nil, errNoHandlers
	}
	return slog.New(slog.NewMultiHandler(handlers...)), nil
}

package logfan

import (
	"context"
	"log/slog"
	"sync"
	"testing"
	"time"
)

func TestNewRing_InvalidCapacity(t *testing.T) {
	_, err := NewRing(0)
	if err == nil {
		t.Fatal("expected error for capacity 0")
	}
	_, err = NewRing(-1)
	if err == nil {
		t.Fatal("expected error for capacity -1")
	}
}

func TestNewRing_ValidCapacity(t *testing.T) {
	r, err := NewRing(5)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if r == nil {
		t.Fatal("expected non-nil Ring")
	}
}

func TestRing_RecordsEmpty(t *testing.T) {
	r, _ := NewRing(5)
	recs := r.Records()
	if len(recs) != 0 {
		t.Fatalf("expected 0 records, got %d", len(recs))
	}
}

func TestRing_HandleAndRetrieve(t *testing.T) {
	r, _ := NewRing(3)
	now := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)

	mustHandle(t, r, slog.NewRecord(now, slog.LevelInfo, "msg1", 0))
	mustHandle(t, r, slog.NewRecord(now, slog.LevelWarn, "msg2", 0))

	recs := r.Records()
	if len(recs) != 2 {
		t.Fatalf("expected 2 records, got %d", len(recs))
	}
	if recs[0].Message != "msg1" {
		t.Errorf("expected msg1 first, got %s", recs[0].Message)
	}
	if recs[1].Message != "msg2" {
		t.Errorf("expected msg2 second, got %s", recs[1].Message)
	}
}

func TestRing_Eviction(t *testing.T) {
	r, _ := NewRing(3)
	now := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)

	for i := range 5 {
		mustHandle(t, r, slog.NewRecord(now, slog.LevelInfo, sprintf("msg%d", i+1), 0))
	}

	recs := r.Records()
	if len(recs) != 3 {
		t.Fatalf("expected 3 records (capacity), got %d", len(recs))
	}
	// Oldest 2 evicted, so msg3, msg4, msg5 remain
	expected := []string{"msg3", "msg4", "msg5"}
	for i, msg := range expected {
		if recs[i].Message != msg {
			t.Errorf("recs[%d] = %s, want %s", i, recs[i].Message, msg)
		}
	}
}

func TestRing_RecordsCopyIndependence(t *testing.T) {
	r, _ := NewRing(3)
	now := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)

	mustHandle(t, r, slog.NewRecord(now, slog.LevelInfo, "msg", 0))

	recs := r.Records()
	recs[0].Message = "tampered"

	// After mutation of returned slice, the ring should be unaffected
	r2 := r.Records()
	if r2[0].Message != "msg" {
		t.Errorf("ring was mutated via returned slice: got %s", r2[0].Message)
	}
}

func TestRing_WithAttrs(t *testing.T) {
	r, _ := NewRing(5)
	h := r.WithAttrs([]slog.Attr{slog.String("key", "val")})
	now := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)

	mustHandle(t, h.(*Ring), slog.NewRecord(now, slog.LevelInfo, "msg", 0))

	recs := r.Records()
	if len(recs) != 1 {
		t.Fatalf("expected 1 record, got %d", len(recs))
	}
	var got string
	recs[0].Attrs(func(a slog.Attr) bool {
		got = a.Value.String()
		return false
	})
	if got != "val" {
		t.Errorf("expected attr val, got %s", got)
	}
}

func TestRing_WithGroup(t *testing.T) {
	r, _ := NewRing(5)
	h := r.WithGroup("g1").WithAttrs([]slog.Attr{slog.String("k", "v")})
	now := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)

	mustHandle(t, h.(*Ring), slog.NewRecord(now, slog.LevelInfo, "msg", 0))

	recs := r.Records()
	if len(recs) != 1 {
		t.Fatalf("expected 1 record, got %d", len(recs))
	}
	var found bool
	recs[0].Attrs(func(a slog.Attr) bool {
		if a.Key == "g1" {
			found = true
			a.Value.Group(func(ga slog.Attr) bool {
				if ga.Key == "k" && ga.Value.String() == "v" {
					return false
				}
				return true
			})
		}
		return true
	})
	if !found {
		t.Error("expected group g1 with attr k=v")
	}
}

func TestRing_Enabled(t *testing.T) {
	r, _ := NewRing(5)
	if !r.Enabled(context.Background(), slog.LevelDebug) {
		t.Error("expected debug to be enabled")
	}
}

func TestRing_ConcurrentSafety(t *testing.T) {
	r, _ := NewRing(100)
	now := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)

	var wg sync.WaitGroup
	for range 20 {
		wg.Go(func() {
			mustHandle(t, r, slog.NewRecord(now, slog.LevelInfo, "concurrent", 0))
		})
	}
	wg.Wait()

	recs := r.Records()
	if len(recs) == 0 {
		t.Error("expected records after concurrent writes")
	}
}

func TestNew_NoHandlers(t *testing.T) {
	_, err := New()
	if err == nil {
		t.Fatal("expected error with no handlers")
	}
}

func TestNew_SingleHandler(t *testing.T) {
	r, _ := NewRing(5)
	logger, err := New(r)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	logger.Info("hello")
	recs := r.Records()
	if len(recs) != 1 {
		t.Fatalf("expected 1 record, got %d", len(recs))
	}
	if recs[0].Message != "hello" {
		t.Errorf("expected 'hello', got '%s'", recs[0].Message)
	}
}

func TestNew_MultipleHandlers(t *testing.T) {
	r1, _ := NewRing(5)
	r2, _ := NewRing(5)
	logger, err := New(r1, r2)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	logger.Info("broadcast")

	if len(r1.Records()) != 1 {
		t.Errorf("r1: expected 1 record, got %d", len(r1.Records()))
	}
	if len(r2.Records()) != 1 {
		t.Errorf("r2: expected 1 record, got %d", len(r2.Records()))
	}
}

func mustHandle(t *testing.T, r *Ring, rec slog.Record) {
	t.Helper()
	if err := r.Handle(context.Background(), rec); err != nil {
		t.Fatalf("Handle failed: %v", err)
	}
}

// sprintf exists because the test uses a 1..5 range loop with i+1
// which produces an int expression, not a string.
func sprintf(format string, args ...any) string {
	return fmt.Sprintf(format, args...)
}

